  "fragment SearchTemplateFields on TemplateSummary {\n  id\n  name\n  manufacturer\n  faction\n  templateImageUrl: imageUrl\n  thumbnailUrl\n  categories\n  kind\n  folderId\n  sourceId\n  sourceName\n  sourceLogoUrl\n  schemeCount\n  paintCount\n}\n\nquery SearchFolderContents($kind: FolderKind!, $search: String!, $folderId: ID, $ownership: Ownership, $stage: PaintingStatus, $category: String, $sourceId: ID, $noSource: Boolean = false, $first: Int! = 48, $after: String) {\n  folderSearch(\n    kind: $kind\n    search: $search\n    folderId: $folderId\n    ownership: $ownership\n    stage: $stage\n    category: $category\n    sourceId: $sourceId\n    noSource: $noSource\n    first: $first\n    after: $after\n  ) {\n    revision {\n      epoch\n      seq\n    }\n    results {\n      totalCount\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n      nodes {\n        __typename\n        ... on Folder {\n          id\n          name\n          parentId\n          directCount\n          recursiveCount\n          coverThumbnailUrl\n        }\n        ... on Miniature {\n          ...MiniatureTile\n        }\n        ... on TemplateSummary {\n          ...SearchTemplateFields\n        }\n      }\n    }\n  }\n}": typeof types.SearchTemplateFieldsFragmentDoc;
  "query BrowseFolders($kind: FolderKind!, $first: Int! = 100, $after: String) {\n  folderBrowser(kind: $kind, flat: true, first: $first, after: $after) {\n    revision {\n      epoch\n      seq\n    }\n    totalCount\n    pageInfo {\n      hasNextPage\n      endCursor\n    }\n    folders {\n      id\n      name\n      parentId\n      directCount\n      recursiveCount\n      coverThumbnailUrl\n    }\n  }\n}\n\nmutation CreateBrowserFolder($kind: FolderKind!, $name: String!, $parentId: ID) {\n  createFolder(kind: $kind, name: $name, parentId: $parentId) {\n    revision {\n      epoch\n      seq\n    }\n    invalidatedFamilies\n  }\n}\n\nmutation RenameBrowserFolder($id: ID!, $name: String!) {\n  renameFolder(id: $id, name: $name) {\n    revision {\n      epoch\n      seq\n    }\n    invalidatedFamilies\n  }\n}\n\nmutation MoveBrowserFolder($id: ID!, $parentId: ID) {\n  moveFolder(id: $id, parentId: $parentId) {\n    revision {\n      epoch\n      seq\n    }\n    invalidatedFamilies\n  }\n}\n\nmutation DeleteBrowserFolder($id: ID!, $mode: FolderDeleteMode!) {\n  deleteFolder(id: $id, mode: $mode) {\n    revision {\n      epoch\n      seq\n    }\n    invalidatedFamilies\n  }\n}\n\nmutation MoveBrowserFolderItems($kind: FolderKind!, $ids: [ID!]!, $folderId: ID) {\n  moveFolderItems(kind: $kind, ids: $ids, folderId: $folderId) {\n    revision {\n      epoch\n      seq\n    }\n    invalidatedFamilies\n  }\n}": typeof types.BrowseFoldersDocument;
