  "query ProjectMiniatureDetails($id: ID!, $recipeAfter: String, $schemesAfter: String, $missingAfter: String, $requiredAfter: String) {\n  miniature(id: $id) {\n    revision {\n      epoch\n      seq\n    }\n    miniature {\n      id\n      folderId\n      title\n      status\n      paintingStatus\n      imageUrl\n      createdAt\n      notes\n      manufacturer\n      faction\n      scale\n    }\n    recipeSteps\n    recipe(first: 40, after: $recipeAfter) {\n      nodes {\n        id\n        paint {\n          ...DetailPaint\n        }\n        step\n        notes\n        sortOrder\n      }\n      totalCount\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n    }\n    schemes(first: 40, after: $schemesAfter) {\n      nodes {\n        id\n        sortOrder\n        scheme {\n          id\n          name\n          category\n          isSystem\n          sourceName\n          sourceLogoUrl\n        }\n      }\n      totalCount\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n    }\n    missing(first: 40, after: $missingAfter) {\n      nodes {\n        id\n        paint {\n          ...DetailPaint\n        }\n        missingStock\n        brokenSubstitution\n      }\n      totalCount\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n    }\n    required(first: 40, after: $requiredAfter) {\n      nodes {\n        ...DetailPaint\n      }\n      totalCount\n      pageInfo {\n        hasNextPage\n        endCursor\n      }\n    }\n  }\n}": typeof types.ProjectMiniatureDetailsDocument;
