  "query SchemesPage($after: String, $search: String, $category: String, $sourceId: ID, $noSource: Boolean!, $readiness: SchemeReadiness, $usesPaintIds: [ID!]!) {\n  schemes(\n    first: 48\n    after: $after\n    search: $search\n    category: $category\n    sourceId: $sourceId\n    noSource: $noSource\n    readiness: $readiness\n    usesPaintIds: $usesPaintIds\n  ) {\n    revision {\n      epoch\n      seq\n    }\n    nodes {\n      ...MiniatureSchemeSummary\n      sourceId\n      paintNames\n      usageCount\n      gradient\n      previewMoreCount\n    }\n    totalCount\n    pageInfo {\n      hasNextPage\n      endCursor\n    }\n    facets {\n      categories {\n        key\n        label\n        count\n      }\n      sources {\n        key\n        label\n        count\n      }\n      readiness {\n        key\n        label\n        count\n      }\n    }\n  }\n}\n\nquery SchemeUsedPaintOptions($search: String!, $excludeIds: [ID!]!) {\n  schemePaintOptions(search: $search, excludeIds: $excludeIds, first: 30) {\n    revision {\n      epoch\n      seq\n    }\n    items {\n      ...DetailPaint\n    }\n  }\n}\n\nfragment SchemeEditResult on SchemeMutationPayload {\n  revision {\n    epoch\n    seq\n  }\n  schemeId\n  invalidatedFamilies\n  clientMutationId\n}\n\nmutation CreateColorScheme($input: SchemeInput!, $clientMutationId: String) {\n  createScheme(input: $input, clientMutationId: $clientMutationId) {\n    ...SchemeEditResult\n  }\n}\n\nmutation UpdateColorScheme($id: ID!, $input: SchemeInput!, $clientMutationId: String) {\n  updateScheme(id: $id, input: $input, clientMutationId: $clientMutationId) {\n    ...SchemeEditResult\n  }\n}\n\nmutation DeleteColorScheme($id: ID!, $clientMutationId: String) {\n  deleteScheme(id: $id, clientMutationId: $clientMutationId) {\n    ...SchemeEditResult\n  }\n}": typeof types.SchemesPageDocument;
